// Der Agent darf hier nie einen Fehler zurückbekommen. Er ist mitten im
// Gespräch; eine Fehlermeldung im Werkzeugergebnis bringt ihn dazu, dem
// Anrufer etwas von technischen Problemen zu erzählen. Das interessiert
// niemanden — die Notiz nachzureichen ist unsere Aufgabe, nicht seine.
//
// Geht das Schreiben schief, greift der Post-Call-Workflow: er bekommt die
// vollständige Abschrift und legt den Anruf dann eben dort an.

const a = $input.first().json;
const ok = a.statusCode >= 200 && a.statusCode < 300;

if (!ok) {
  console.error(`Notiz nicht gespeichert (HTTP ${a.statusCode}): ${JSON.stringify(a.body).slice(0, 300)}`);
}

return [{ json: { ok: true, bestaetigung: 'Notiert.' } }];
